			block.builders.hydrate.addLine(
				`@encapsulateStyles(${name});`
			);

			if (this._cssRefAttribute) {
				block.builders.hydrate.addLine(
					`@setAttribute(${name}, "svelte-ref-${this._cssRefAttribute}", "");`
