	addBindings(
		block: Block,
		allUsedContexts: Set<string>
	) {
		const bindings: Binding[] = this.attributes.filter((a: Binding) => a.type === 'Binding');
		if (bindings.length === 0) return;

		if (this.name === 'select' || this.isMediaNode()) this.generator.hasComplexBindings = true;

